import logging
from taf.internal.file.transfer.base import FileGetter
from taf.internal.managedobject import Using
from .file_transfer_base import CatFileTransfer

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CatFileGetter(Using('remote_executor'),
                    Using('local_executor'),
                    FileGetter,
                    CatFileTransfer):
    """
    Object, which allows to get files from a remote host to the local host.
    """

    def get_file(self, source_path, target_path):
        logger.debug(
            "getting {source_path!r} into {target_path!r}".format(
                source_path=source_path,
                target_path=target_path))
        self._transfer_file(source_path=source_path,
                            target_path=target_path,
                            source_executor=self._remote_executor,
                            target_executor=self._local_executor)
